message.content:
{
  "avaliacoes": [
    {
      "criterio": "aderencia_curricular",
      "nota": 3,
      "justificativa": "Os conteúdos (conceito, seleção e resolução colaborativa) e as atividades ET1‑ET3 estão diretamente ligados à habilidade EF08CO04, exercitando a identificação da estrutura de dados adequada (OBJ1) e a demonstração da solução (OBJ2)."
    },
    {
      "criterio": "alinhamento_objetivos",
      "nota": 3,
      "justificativa": "OBJ1 e OBJ2 são descritos com verbos observáveis (identificar, demonstrar) e são distintos; ambos desdobram o objetivo geral e se alinham à habilidade."
    },
    {
      "criterio": "coerencia_metodologica",
      "nota": 3,
      "justificativa": "A metodologia desplugada declarada (explicação, trabalho em grupo, apresentação) aparece nas etapas ET1, ET2 e ET3, com sequência lógica de introdução, análise e síntese."
    },
    {
      "criterio": "viabilidade",
      "nota": 3,
      "justificativa": "Os recursos (quadro, pincel, material impresso) são os mesmos citados nas atividades; a soma dos tempos (15+25+20=60) corresponde à duração total e é realista para as tarefas propostas."
    },
    {
      "criterio": "avaliacao_aprendizagem",
      "nota": 2,
      "justificativa": "EVI1 e EVI2 são observáveis e os instrumentos INS1 e INS2 coletam as evidências, porém não há rubrica detalhada que permita distinguir desempenho adequado de inadequado."
    },
    {
      "criterio": "inclusao",
      "nota": 3,
      "justificativa": "As adaptações ADP1 e ADP2 oferecem alternativas concretas para estudantes com dificuldades de leitura ou expressão, mantendo os mesmos objetivos e recursos."
    }
  ],
  "falhas": [
    {
      "id": "F1",
      "criterio": "avaliacao_aprendizagem",
      "componente": "avaliacao_preliminar",
      "gravidade": "maior",
      "descricao": "Os instrumentos de avaliação (INS1, INS2) não apresentam rubrica ou critérios de desempenho claros, dificultando a distinção entre desempenho adequado e inadequado.",
      "correcao_sugerida": "Incluir uma rubrica com níveis de desempenho (por exemplo, insuficiente, satisfatório, excelente) para cada evidência, especificando indicadores observáveis que permitam ao professor avaliar o grau de domínio dos objetivos."
    }
  ],
  "resumo": "O plano atende de forma adequada à habilidade EF08CO04, com objetivos claros, metodologia coerente e viável, e adaptações inclusivas. Apenas a avaliação carece de rubrica detalhada para discriminar o desempenho dos estudantes."
}

